python3 - <<'E'
p='src/app.ts'
s=open(p).read()
a=s.index('  app.get("/orders"')
b=s.index('  app.use((err')
new='''  const PAGE_SIZE = 20;

  // Cursor is the opaque base64url id of the last order on the previous page.
  function decodeCursor(raw: string): number | null {
    const text = Buffer.from(raw, "base64url").toString("utf8");
    if (!/^\\d{1,9}$/.test(text)) return null;
    const id = Number(text);
    return id <= 2147483647 ? id : null;
  }

  app.get("/orders", async (req, res) => {
    let before: number | null = null;
    if (req.query.cursor !== undefined) {
      if (typeof req.query.cursor !== "string") return sendError(res, 400, "invalid_cursor", "Invalid cursor");
      before = decodeCursor(req.query.cursor);
      if (before === null) return sendError(res, 400, "invalid_cursor", "Invalid cursor");
    }
    const { rows } = await pool.query(
      `select id, status, total_cents, created_at from orders
       where user_id = $1 and ($2::int is null or id < $2)
       order by id desc limit $3`,
      [res.locals.user.id, before, PAGE_SIZE + 1],
    );
    const hasMore = rows.length > PAGE_SIZE;
    const orders = rows.slice(0, PAGE_SIZE);
    const nextCursor = hasMore ? Buffer.from(String(orders[orders.length - 1].id)).toString("base64url") : null;
    res.json({ orders, nextCursor });
  });

'''
open(p,'w').write(s[:a]+new+s[b:])

